test_that("every GoogleSites registry row resolves to the family routine", {
  reg <- read.csv(here::here("k12_district_registry.csv"), stringsAsFactors = FALSE)
  for (d in reg$District[reg$Platform == "GoogleSites"]) expect_equal(edjobs::resolve_scraper_call(d)$fn, "fetch_googlesites_postings", info = d)
  expect_equal(edjobs::resolve_scraper_call("Cut Bank School District #15")$args[[3]], "^Open Positions")
})
